rows = [json.loads(line) for line in PATH.read_text(encoding="utf-8").splitlines() if line.strip()]
by_id = {row["id"]: row for row in rows}
unit_ids = [f"ar-b2-u01-p{i:02d}" for i in range(1, 7)]
assert all(pid in by_id for pid in unit_ids)

before_targets = {pid: [(t["id"], t["form"], t.get("exposures_in_text")) for t in by_id[pid].get("new_lexical_targets", [])] for pid in unit_ids}
changes = []

for pid in unit_ids:
    row = by_id[pid]
    assert row["cefr"] == "B2" and row["unit"] == 1, pid
    addition = ADD[pid].strip()
    assert addition not in row["text"], f"{pid}: addition already present"
    row["text"] = row["text"].rstrip() + " " + addition

    q_by_id = {q["id"]: q for q in row["questions"]}
    a_by_qid = {a["question_id"]: a for a in row["answer_key"]}
    for qid, (qtype, prompt, target_ids, answer) in UPDATES[pid].items():
        q = q_by_id[qid]
        old = {"type": q["type"], "prompt": q["prompt"], "target_ids": q.get("target_ids")}
        q["type"] = qtype
        q["prompt"] = prompt
        if target_ids is None:
            q.pop("target_ids", None)
        else:
            q["target_ids"] = target_ids
        a_by_qid[qid]["answer"] = answer
        changes.append({"passage_id": pid, "question_id": qid, "old": old, "new_type": qtype})

    row["word_count"] = len(row["text"].split())
    row["sentence_count"] = len(re.findall(r"[.!؟]+", row["text"]))
    row["revision"] = int(row.get("revision", 1)) + 1
    note = "Final Pass 03/07 remediation: expanded B2 Unit 01 into the 350–550-word production band with layered evidence-to-action reasoning and recalibrated synthesis/grammar assessment while preserving lexical target contracts."
    notes = row.setdefault("quality", {}).setdefault("notes", [])
    if note not in notes:
        notes.append(note)

    assert 350 <= row["word_count"] <= 550, (pid, row["word_count"])
    assert len(row["questions"]) == 10 and len(row["answer_key"]) == 10, pid
    assert before_targets[pid] == [(t["id"], t["form"], t.get("exposures_in_text")) for t in row.get("new_lexical_targets", [])], pid
    for target in row.get("new_lexical_targets", []):
        assert target["form"] in row["text"], (pid, target["form"])

    types = [q["type"] for q in row["questions"]]
    assert sum(t in COMP for t in types) >= 4, (pid, "comp", types)
    assert sum(t in LEX for t in types) >= 2, (pid, "lex", types)
    assert sum(t in GRAM for t in types) >= 2, (pid, "gram", types)
    assert sum(t in SYN for t in types) >= 1, (pid, "syn", types)

p06 = by_id["ar-b2-u01-p06"]
assert p06["new_lexical_targets"] == []
assert p06["speed_training"]["new_word_policy"] == "none"
assert p06["speed_training"]["timed"] is True
assert len(changes) == 18, len(changes)

PATH.write_text("\n".join(json.dumps(row, ensure_ascii=False, sort_keys=True) for row in rows) + "\n", encoding="utf-8")

print(json.dumps({"unit": "B2 Unit 01", "passages": [{"id": pid, "word_count": by_id[pid]["word_count"]} for pid in unit_ids], "question_changes": len(changes), "p06_new_lexical_targets": len(p06["new_lexical_targets"])}, ensure_ascii=False))
